reset role;
insert into public.sample_requests(id,opportunity_id,status,note) select 'old-private-sample',opportunity_id,'sent','OLDER_COMMERCIAL_HISTORY' from public.partner_network_referrals where id='00000000-0000-4000-8000-000000000901';
insert into public.trade_quotes(id,opportunity_id,status,note) select 'old-private-quote',opportunity_id,'draft','OLDER_COMMERCIAL_HISTORY' from public.partner_network_referrals where id='00000000-0000-4000-8000-000000000901';
insert into public.receivables(id,order_id,total,paid,status) select 'integration-r-'||o.id,o.id,o.estimated_total,o.estimated_total,'paid' from public.orders o where o.id in(current_setting('test.retail_first'),current_setting('test.retail_repeat'),current_setting('test.retail_direct'));
insert into public.receivable_payments(id,receivable_id,amount) select 'integration-p-'||id,id,total from public.receivables where id like 'integration-r-%';
update public.orders set status='completed',delivered_at=now() where id in(current_setting('test.retail_first'),current_setting('test.retail_repeat'),current_setting('test.retail_direct'));
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
select public.partner_network_reconcile(current_setting('test.retail_first'),'{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"internal_cost_total":30000,"minimum_retained_profit":10000,"review_note":"Synthetic integration actual costs confirmed"}');
select public.partner_network_reconcile(current_setting('test.retail_repeat'),'{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"internal_cost_total":30000,"minimum_retained_profit":10000,"review_note":"Synthetic integration repeat source confirmed"}');
select public.partner_network_reconcile(current_setting('test.retail_direct'),'{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"internal_cost_total":30000,"minimum_retained_profit":10000,"review_note":"Synthetic integration verified offline source"}');
select public.test_assert((select rate_percent=1 and commission_basis='profit' and calculated_amount=700 from public.partner_network_commissions where order_id=current_setting('test.retail_first')),'retail Classic first order uses 1 percent profit');
select public.test_assert((select rate_percent=1 and calculated_amount=700 from public.partner_network_commissions where order_id=current_setting('test.retail_repeat')),'retail second order stays 1 percent');
select public.test_assert((select rate_percent=2 and calculated_amount=1400 from public.partner_network_commissions where order_id=current_setting('test.retail_direct')),'verified third retail source uses 2 percent profit');
select public.test_assert(public.partner_network_admin_snapshot() ?& array['quote_proposals','quote_catalog','rewards'],'admin combined snapshot composes all modules');
select public.test_assert((select count(*)=3 from jsonb_array_elements(public.partner_network_admin_snapshot()->'orders')o where o->>'type'='retail' and o->>'partner_id'='00000000-0000-4000-8000-000000000801'),'manager sees the exact three accepted retail orders');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',false);
select public.test_assert((public.partner_network_snapshot()->'referrals'->0->'samples')='[]' and (public.partner_network_snapshot()->'referrals'->0->'quotes')='[]','retail consent never exposes older CRM samples or quotes');
select public.test_assert(jsonb_array_length(public.partner_network_snapshot()->'orders')=3,'own progress shows only explicitly attributed orders');
select public.test_assert(jsonb_array_length(public.partner_network_snapshot()->'commissions')=3,'shared commission ledger works for own retail orders');
select public.test_assert(position('internal_cost_total' in (public.partner_network_snapshot()->'rewards')::text)=0,'own rewards do not leak source cost rows');
select public.test_error('select public.partner_network_admin_snapshot()','manager_required');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',false);
select public.test_assert(public.partner_network_snapshot()->'orders'='[]' and public.partner_network_snapshot()->'commissions'='[]','second partner sees no other partner sales or commissions');
reset role;

-- Full quote -> fulfilment -> real collected difference, through the shared finance engine.
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
select public.partner_network_release_quote_terms('00000000-0000-4000-8000-000000000901',jsonb_build_object('request_id','00000000-0000-4000-8000-000000008888','expected_revision',0,'remuneration_mode','price_difference','valid_until',current_date+14,'commercial_terms','Synthetic price-difference integration','reason','Manager approves synthetic base','lines','[{"product_id":"retail-test","unit":"kg","min_qty":1,"max_qty":10,"base_price":80000}]'::jsonb));
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',false);
select public.partner_network_propose_quote('00000000-0000-4000-8000-000000008888','{"expected_revision":1,"lines":[{"product_id":"retail-test","unit":"kg","qty":10,"price":100000}]}');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
select public.partner_network_review_quote_proposal('00000000-0000-4000-8000-000000008888','approve','{"expected_revision":2,"reason":"Confirmed synthetic commercial terms"}');
reset role;
insert into public.orders(id,type,status,quote_id,lines,estimated_total) select 'integration-difference','wholesale','pending',q.id,q.lines,q.total from public.trade_quotes q where q.id='quote-partner-00000000000040008000000000008888';
insert into public.receivables(id,order_id,total,paid,status) values('integration-diff-r','integration-difference',1000000,1000000,'paid');
insert into public.receivable_payments(id,receivable_id,amount) values('integration-diff-p','integration-diff-r',1000000);
set role authenticated;
select public.test_error($q$select public.partner_network_reconcile('integration-difference','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"internal_cost_total":600000,"minimum_retained_profit":100000,"review_note":"Cannot settle before completed fulfilment"}')$q$,'price_difference_terms_invalid');
reset role;
update public.orders set status='completed',delivered_at=now() where id='integration-difference';
set role authenticated;
select public.partner_network_reconcile('integration-difference','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"internal_cost_total":600000,"minimum_retained_profit":100000,"review_note":"Actual synthetic costs reviewed for difference"}');
select public.test_assert((select remuneration_mode='price_difference' and calculated_amount=200000 and classic_agreement_id is null from public.partner_network_commissions where order_id='integration-difference'),'price difference is 200k and does not stack with Classic');
select public.test_error($q$select public.partner_network_reconcile('integration-difference','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"rate_percent":2,"review_note":"Cannot add a percentage to price difference"}')$q$,'price_difference_no_percentage_stacking');
select public.partner_network_commission_action((select id from public.partner_network_commissions where order_id='integration-difference'),'approve','{}');
select public.partner_network_commission_action((select id from public.partner_network_commissions where order_id='integration-difference'),'pay',jsonb_build_object('amount',200000,'reference','synthetic-difference-transfer','paid_at',now()));
reset role;
update public.orders set lines=jsonb_set(lines,'{0,qty}','5') where id='integration-difference';
select public.test_assert((select (public.partner_network_commission_view(id)->>'current_amount')::numeric=100000 and (public.partner_network_commission_view(id)->>'overpaid_amount')::numeric=100000 from public.partner_network_commissions where order_id='integration-difference'),'reduced quantity caps commission at approved goods value, even if overpayment remains collected');
select public.test_assert((select paid_amount=200000 and calculated_amount=200000 from public.partner_network_commissions where order_id='integration-difference'),'historical difference payout never rewritten');
update public.orders set lines=jsonb_set(lines,'{0,price}','90000') where id='integration-difference';
select public.test_assert((select (public.partner_network_commission_view(id)->>'stale')::boolean and public.partner_network_commission_view(id)->'current_amount'='null' from public.partner_network_commissions where order_id='integration-difference'),'unapproved order price changes need commercial review');
